// Cleans the form input and validates the NIP checksum and the bank account (IBAN mod 97).
const s = $('Settings').first().json;
return $input.all().map((item) => {
  const f = item.json;
  const errors = [];
  const nip = String(f['Supplier NIP'] ?? '').replace(/^PL/i, '').replace(/[^0-9]/g, '');
  const account = String(f['Bank account number'] ?? '').toUpperCase().replace(/^PL/, '').replace(/[^0-9]/g, '');

  if (nip.length !== 10) {
    errors.push('NIP must have 10 digits.');
  } else {
    const w = [6, 5, 7, 2, 3, 4, 5, 6, 7];
    const sum = w.reduce((acc, weight, i) => acc + weight * Number(nip[i]), 0);
    if (sum % 11 === 10 || sum % 11 !== Number(nip[9])) errors.push('NIP checksum is invalid. Check for typos.');
  }

  if (account.length !== 26) {
    errors.push('Bank account must have 26 digits (Polish NRB), optionally with the PL prefix.');
  } else {
    // IBAN check: move "PL" + check digits to the end, P=25, L=21, remainder must be 1
    const rearranged = account.slice(2) + '2521' + account.slice(0, 2);
    let rem = 0;
    for (const ch of rearranged) rem = (rem * 10 + Number(ch)) % 97;
    if (rem !== 1) errors.push('Bank account checksum is invalid. Check for typos.');
  }

  const amount = Number(String(f['Gross amount (PLN)'] ?? '').replace(',', '.')) || 0;
  return {
    json: {
      valid: errors.length === 0,
      errors,
      nip,
      account,
      invoice_number: String(f['Invoice number'] ?? '').trim().slice(0, 100),
      amount_pln: amount,
      date: $now.setZone(s.timezone || 'Europe/Warsaw').toFormat('yyyy-MM-dd'),
    },
  };
});

// Combines the search and check responses into one verdict and one log row.
const s = $('Settings').first().json;
return $input.all().map((item, i) => {
  const input = $('Clean and validate input').all()[i]?.json ?? $('Clean and validate input').first().json;
  const searchRes = $('Look up VAT status').all()[i]?.json ?? {};
  const checkRes = item.json ?? {};
  const subject = searchRes.body?.result?.subject ?? null;
  const assigned = checkRes.body?.result?.accountAssigned ?? null; // "TAK" or "NIE"
  const requestId = checkRes.body?.result?.requestId ?? searchRes.body?.result?.requestId ?? '';
  const apiError = [searchRes, checkRes]
    .filter((r) => (r.statusCode ?? 0) !== 200)
    .map((r) => `${r.statusCode ?? 'no response'} ${r.body?.code ?? ''} ${r.body?.message ?? ''}`.trim());
  const large = input.amount_pln > Number(s.largePaymentThresholdPln || 15000);
  const status = subject?.statusVat ?? (subject === null && !apiError.length ? 'Not found' : '');

  let verdict, headline, notes;
  if (apiError.length) {
    verdict = 'ERROR'; headline = '⚠️ The White List could not be checked';
    notes = `API error: ${apiError.join(' | ')}. Try again later or check manually at wykazpodatnikowvat.mf.gov.pl.`;
  } else if (assigned === 'TAK') {
    verdict = 'OK'; headline = '✅ Account is on the White List';
    notes = 'The account is assigned to this NIP today. Keep the requestId as proof of the check.';
  } else if (!subject) {
    verdict = 'NOT_FOUND'; headline = '⛔ NIP not found in the VAT register';
    notes = 'The supplier is not in the VAT taxpayer list. Confirm the NIP with the supplier before paying.';
  } else if (status !== 'Czynny') {
    verdict = 'CHECK'; headline = `⚠️ Supplier VAT status: ${status}`;
    notes = 'Accounts are only listed for active VAT payers. Check whether White List rules apply to this payment.';
  } else {
    verdict = 'NOT_ON_LIST'; headline = '⛔ Account is NOT on the White List';
    notes = 'Do not pay to this account without confirming it with the supplier.' +
      (large ? ` The amount is over ${Number(s.largePaymentThresholdPln).toLocaleString("en-US")} PLN: paying to an unlisted account may make the cost non-deductible unless you file ZAW-NR in time.` : '');
  }

  const row = {
    checked_at: $now.toUTC().toISO(),
    supplier_nip: input.nip,
    supplier_name: subject?.name ?? '',
    bank_account: input.account,
    invoice_number: input.invoice_number,
    amount_pln: input.amount_pln,
    vat_status: status,
    account_on_list: assigned === 'TAK' ? 'YES' : assigned === 'NIE' ? 'NO' : 'UNKNOWN',
    verdict,
    request_id: requestId,
    notes,
  };
  const message = [
    row.supplier_name ? `Supplier: ${row.supplier_name} (NIP ${row.supplier_nip})` : `NIP: ${row.supplier_nip}`,
    `VAT status: ${row.vat_status || 'unknown'}`,
    `Account: ${row.bank_account}`,
    `Account on the list today: ${row.account_on_list}`,
    '',
    notes,
    '',
    requestId ? `Proof of check (requestId): ${requestId}` : '',
  ].filter((l, idx, arr) => l !== '' || arr[idx - 1] !== '').join('\n');
  return { json: { ...row, headline, message } };
});
